import {buildGraph,makeArea,journey,coordinates,unproject} from './engine.js';
let graph;
self.onmessage=({data})=>{try{if(data.type==='build'){graph=buildGraph(data.raw,makeArea(data.geometry));postMessage({type:'built',stats:{nodes:graph.nodes.size,edges:graph.edges.length,omitted:graph.omitted},roads:graph.roads});}else if(data.type==='route'){const result=journey(graph,data.a,data.b,data.stations,data.settings);const serialize=j=>j?{...j,legs:j.legs.map(l=>({...l,prev:undefined,edge:undefined,path:l.path.map(e=>({...e})),points:coordinates(graph,l),geojson:{type:'Feature',properties:{mode:l.mode},geometry:{type:'LineString',coordinates:coordinates(graph,l).map(unproject)}}}))}:null;postMessage({type:'route',id:data.id,result:{...result,shortest:serialize(result.shortest),cheapest:serialize(result.cheapest)}});}}catch(error){postMessage({type:'error',id:data.id,message:error.message});}};
